const LIMITE_DIA = 60;
const LIMITE_CONVERSA = 15;
const TAMANHO_MAXIMO = 400;

const item = $input.first().json;
const texto = String(item.chatInput || '').trim();
const sessao = String(item.sessionId || 'sem-sessao').slice(0, 80);
const dados = $getWorkflowStaticData('global');
const dia = new Date().toISOString().slice(0, 10);

if (dados.dia !== dia) {
  dados.dia = dia;
  dados.total = 0;
  dados.sessoes = {};
}

let aviso = '';
if (!texto) aviso = 'Escreva uma pergunta para começar.';
else if (texto.length > TAMANHO_MAXIMO) aviso = 'Essa mensagem ficou longa. Envie uma pergunta com até 400 caracteres.';
else if (dados.total >= LIMITE_DIA) aviso = 'A demonstração atingiu o limite de hoje. Volte amanhã para testar.';
else if ((dados.sessoes[sessao] || 0) >= LIMITE_CONVERSA) aviso = 'Esta conversa atingiu o limite de 15 perguntas. Recarregue a página para começar outra.';

if (!aviso) {
  dados.total += 1;
  dados.sessoes[sessao] = (dados.sessoes[sessao] || 0) + 1;
}

return [{ json: { ...item, chatInput: texto, pode_seguir: !aviso, aviso, uso_hoje: dados.total } }];
